const questionGroups: readonly {
  category: AZ900Category
  questions: readonly QuestionDraft[]
}[] = [
  { category: "Cloud concepts", questions: cloudQuestions },
  { category: "Azure architecture and services", questions: architectureQuestions },
  { category: "Azure management and governance", questions: governanceQuestions },
]

export const additionalAZ900Questions: AZ900Question[] = questionGroups.flatMap(
  ({ category, questions }) =>
    questions.map(([objective, question, correctAnswer, explanation], index) => {
      const incorrectOptions = distractors[category].filter(
        (option) => option !== correctAnswer,
      )
      const offset = (index * 3) % incorrectOptions.length
      const options = [
        correctAnswer,
        incorrectOptions[offset],
        incorrectOptions[(offset + 1) % incorrectOptions.length],
        incorrectOptions[(offset + 2) % incorrectOptions.length],
      ] as [string, string, string, string]
      const id = `added-${String(
        questionGroups
          .slice(0, questionGroups.findIndex((group) => group.category === category))
          .reduce((total, group) => total + group.questions.length, 0) + index + 1,
      ).padStart(3, "0")}`

      return {
        id,
        category,
        objective,
        difficulty: "medium",
        question,
        options,
        correctAnswer,
        explanation,
        verificationStatus: "needs-verification",
      }
    }),
)
